using Captovix;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
internal static class Program{
 [STAThread]static int Main(){int count=0;void Check(bool x,string n){if(!x)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}MediaItem? item=null;string folder=Path.Combine(Path.GetTempPath(),"Captovix-M6-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
 try{var bytes=Enumerable.Repeat((byte)255,640*360*4).ToArray();var original=ImageTransfer.Bitmap(640,360,bytes);var doc=new EditorDocument{OriginalWidth=640,OriginalHeight=360};var a=MockupStudio.Create(new(30,40,230,60),new(0,0,640,360),new("#FFFFFF","#FFFFFF","#0000FF",1));a.Mockup!.Type=MockupKind.Label;a.FontFamily="Times New Roman";a.FontSize=14;a.Italic=true;a.Text="Nội dung gốc";doc.Annotations.Add(a);var session=new EditorSession(doc);var initial=ImageTransfer.Bgra(EditorRenderer.Render(original,doc));
 var type=typeof(MainWindow).Assembly.GetType("Captovix.MockupInspector")!;var inspector=(StackPanel)Activator.CreateInstance(type,true)!;type.GetMethod("Load")!.Invoke(inspector,[a]);var fields=type.GetFields(BindingFlags.NonPublic|BindingFlags.Instance);var italic=(CheckBox)fields.Single(f=>f.Name=="italic").GetValue(inspector)!;var size=(TextBox)fields.Single(f=>f.Name=="size").GetValue(inspector)!;var text=(TextBox)fields.Single(f=>f.Name=="text").GetValue(inspector)!;Check(italic.IsChecked==true&&size.Text=="14","Sidebar shows source italic and14px");type.GetField("Changed")!.SetValue(inspector,(Action<string,MockupChanges>)((id,c)=>session.Change(d=>MockupEditing.Apply(d,id,c))));text.Text="Đã sửa trực tiếp";Check((bool)type.GetMethod("Flush")!.Invoke(inspector,null)!,"Sidebar accepts text without modal");Check(session.Document.Annotations[0].Italic&&session.Document.Annotations[0].FontFamily=="Times New Roman"&&session.Document.Annotations[0].FontSize==14&&session.Document.Annotations[0].TextColor=="#0000FF","Sidebar text-only change preserves source style");var rendered=ImageTransfer.Bgra(EditorRenderer.Render(original,session.Document));Check(!rendered.SequenceEqual(initial),"Changed text alters export pixels");session.Undo();Check(ImageTransfer.Bgra(EditorRenderer.Render(original,session.Document)).SequenceEqual(initial),"Undo restores exact pixels");session.Redo();Check(ImageTransfer.Bgra(EditorRenderer.Render(original,session.Document)).SequenceEqual(rendered),"Redo restores exact pixels");
 var surface=new EditorSurface();surface.Load(original,session);surface.SetZoom(1);surface.Tool=EditorTool.Select;int edits=0;surface.MockupEditRequested+=()=>edits++;surface.PointerDown(new(70,65),clickCount:2);Check(edits==1&&surface.SelectedId==a.Id,"Doubleclick requests existing Mockup editing");
 string path=Path.Combine(folder,"original.png");ImageTransfer.Save(original,path);item=new(){Id=Guid.NewGuid().ToString("N"),FilePath=path};DocumentStore.Save(item,session,original);byte[] old=File.ReadAllBytes(DocumentStore.EditPath(item.Id));session.Change(d=>{d.Annotations[0].Mockup!.SemanticRole="Tab";d.Version=22;});DocumentStore.Save(item,session,original);Check(File.ReadAllBytes(DocumentStore.EditPath(item.Id)+".pre-v1.44.bak").SequenceEqual(old),"Schema22 keeps exact pre-upgrade backup");var reopened=DocumentStore.Load(item,original,out var warning);Check(warning==null&&reopened.Document.Version==22&&ImageTransfer.Bgra(EditorRenderer.Render(original,reopened.Document)).SequenceEqual(rendered),"Sidecar22 reopens with same export pixels");Check(ImageTransfer.Bgra(original).SequenceEqual(bytes),"Source capture quality/pixels unchanged");type.GetMethod("Clear")!.Invoke(inspector,null);Console.WriteLine($"{count} M6 Windows checks passed; manual IME, real form and installer QA still required.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{StaImageWorker.Stop();if(item!=null)foreach(string suffix in new[]{"",".bak",".pre-v1.44.bak",".pre-v1.38.bak",".pre-v1.13.bak"})File.Delete(DocumentStore.EditPath(item.Id)+suffix);Directory.Delete(folder,true);}}
}
